import json, time
from pathlib import Path
mission_ids = {'CATALOGUE-COMMISSIONED-REVIEW-LIVE-TEST', 'WELFARE-LIVE-DEMAND', 'WELFARE-SITE-RETIRE', 'TEXT-CSV-INTAKE-EXPERIMENT'}
def rows(path, key):
    value = json.loads(path.read_text())
    if isinstance(value, list):
        return value
    for field in (key, 'items', 'entries'):
        if isinstance(value.get(field), list):
            return value[field]
    raise ValueError(f'Unexpected page format: {path.name}')
folder = Path('world/pages')
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
for key, fields in [('missions', ('mission_id','status','agent_id','evidence')), ('reviews', ('subject','digest','verdict','host_provider','host_turn','seq'))]:
    pages = sorted(folder.glob(f'{key}-*.json'))
    print(json.dumps({'collection': key, 'pages_read': len(pages)}))
    for page in pages:
        for row in rows(page, key):
            if (key == 'missions' and row.get('mission_id') in mission_ids) or (key == 'reviews' and row.get('subject') == 'site:shopify-catalogue-example' and row.get('digest') == digest):
                print(json.dumps({field: row.get(field) for field in fields}))
print(json.dumps({'observed_at_utc': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())}))
